INSERT INTO `officials` VALUES (1,'Drs. Abd. Najib','drs-abd-najib','19680512 199303 1 005','Kepala Dinas Kependudukan dan Pencatatan Sipil','Pembina Utama Muda / IV c','Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu',NULL,'Drs. Abd. Najib memimpin Dinas Dukcapil Kabupaten Dompu dengan komitmen mewujudkan tertib administrasi kependudukan digital yang inklusif, cepat, dan transparan bagi seluruh warga Kabupaten Dompu.','Memimpin, merumuskan, membinan, dan mengevaluasi pelaksanaan kebijakan daerah di bidang pendaftaran penduduk, pencatatan sipil, serta pengelolaan informasi administrasi kependudukan.','Jl. Bhayangkara No. 01, Kabupaten Dompu, NTB','(0373) 21124','kadis@dukcapil.dompukab.go.id','Senin - Jumat | 07:30 - 16:00 WITA','active',NULL,NULL,1,'2026-07-23 04:19:59','2026-07-23 04:19:59',NULL),(2,'Samsul Bahri, S.E.','samsul-bahri-se','19740915 199903 1 002','Sekretaris Dinas','Pembina / IV a','Sekretariat Dinas Dukcapil',NULL,'Mengordinasikan perencanaan program, pengelolaan keuangan, dan pembinaan kepegawaian internal dinas.','Membantu Kepala Dinas dalam mengoordinasikan perencanaan, pembinaan administrasi, umum, kepegawaian, dan keuangan.','Jl. Bhayangkara No. 01, Dompu','(0373) 21124','sekretaris@dukcapil.dompukab.go.id',NULL,'active',NULL,NULL,2,'2026-07-23 04:21:03','2026-07-23 04:21:03',NULL),(3,'H. Ahmad, S.Sos.','h-ahmad-s-sos','19780310 200501 1 008','Kabid Pelayanan Pendaftaran Penduduk','Penata Tingkat I / III d','Bidang Pendaftaran Penduduk',NULL,'Mengelola pelayanan perekaman KTP-El, penerbitan Kartu Keluarga, dan Kartu Identitas Anak (KIA).',NULL,NULL,NULL,NULL,NULL,'active',NULL,NULL,3,'2026-07-23 04:21:03','2026-07-23 04:21:03',NULL),(4,'Mariam, S.IP.','mariam-s-ip','19810412 200604 2 011','Kabid Pelayanan Pencatatan Sipil','Penata Tingkat I / III d','Bidang Pencatatan Sipil',NULL,'Mengelola penerbitan Akta Kelahiran, Akta Kematian, Akta Perkawinan, dan Akta Perceraian.',NULL,NULL,NULL,NULL,NULL,'active',NULL,NULL,4,'2026-07-23 04:21:03