INSERT INTO `survey_questions` VALUES (1,1,'Bagaimana pendapat Anda tentang kesesuaian persyaratan pelayanan dengan jenis pelayanannya?','rating','Persyaratan Pelayanan',1,1,1,'2026-07-23 07:37:07','2026-07-23 07:37:07'),(2,1,'Bagaimana kemudahan prosedur pelayanan administrasi kependudukan di loket maupun online?','rating','Prosedur Pelayanan',2,1,1,'2026-07-23 07:37:07','2026-07-23 07:37:07'),(3,1,'Bagaimana kecepatan waktu dalam memberikan pelayanan dan penyelesaian dokumen kependudukan?','rating','Waktu Pelayanan',3,1,1,'2026-07-23 07:37:07','2026-07-23 07:37:07'),(4,1,'Bagaimana kepastian dan kejelasan biaya pelayanan (Gratis Rp 0,- sesuai undang-undang)?','rating','Biaya/Tarif',4,1,1,'2026-07-23 07:37:07','2026-07-23 07:37:07'),(5,1,'Bagaimana kesesuaian antara produk hasil pelayanan yang diterima dengan ketentuan yang ditetapkan?','rating','Produk Spesifikasi',5,1,1,'2026-07-23 07:37:07','2026-07-23 07:37:07'),(6,1,'Bagaimana kompetensi, keahlian, dan ketrampilan petugas dalam memberikan pelayanan?','rating','Kompetensi Pelaksana',6,1,1,'2026-07-23 07:37:07','2026-07-23 07:37:07'),(7,1,'Bagaimana perilaku petugas meliputi kesopanan, keramahan, dan kesiapsiagaan dalam merespon pemohon?','rating','Perilaku Pelaksana',7,1,1,'2026-07-23 07:37:07','2026-07-23 07:37:07'),(8,1,'Bagaimana penanganan pengaduan, saran, dan masukan pengguna layanan kependudukan?','rating','Penanganan Pengaduan',8,1,1,'2026-07-23 07:37:07','2026-07-23 07:37:07'),(9,1,'Bagaimana kualitas dan kenyamanan sarana serta prasarana gedung/ruang tunggu pelayanan?','rating','Sarana & Prasarana',9,1,1,'2026-07-23 07:37:07','2026-07-23 07:37:07');
